\set ON_ERROR_STOP on
SET lock_timeout = '5s';
BEGIN;
CREATE TEMP TABLE prof (publisher_id int, name text, iso text, ownership_type text, owner text, classification_tags text[], political_party_association text,
  historical_context text, current_context text, confidence text, evidence_summary text, evidence_sources jsonb, review_required boolean) ON COMMIT DROP;
INSERT INTO prof VALUES
  (8952, $$ACP (Agence Congolaise de Presse)$$, 'CD', $$Agence de presse publique (établissement public, propriété intégrale de l’État)$$, $$État congolais (RDC), sous la tutelle du ministère de la Communication et des Médias ; directeur général nommé par l’État$$, ARRAY['public_state']::text[], NULL, $$Créée le 12 août 1960 par décret du Premier ministre Patrice Lumumba, à partir du bureau de Kinshasa de l’agence belge Belga ; établissement public depuis 1967 ; rebaptisée Agence Zaïre Presse (AZAP) en 1971, puis redevenue ACP.$$, $$Agence officielle financée presque entièrement par des subventions publiques. State Media Monitor la classe « State Controlled Media » : couverture largement alignée sur l’agenda de communication du gouvernement, sans garanties d’autonomie éditoriale.$$, 'high', $$Statut et gouvernance documentés par Wikipédia et State Media Monitor (2026).$$, $$[{"url": "https://statemediamonitor.com/2026/05/agence-congolaise-de-presse-acp/", "note": "State Media Monitor : « State Controlled Media » depuis 2022 ; 100 % public ; tutelle du ministère de la Communication", "category": "media_research", "accessed_at": "2026-10-16"}, {"url": "https://en.wikipedia.org/wiki/Agence_Congolaise_de_Presse", "note": "Créée le 12 août 1960 par décret de Patrice Lumumba ; établissement public sous tutelle du ministère de la Communication et des Médias", "category": "reference", "accessed_at": "2026-10-16"}]$$::jsonb, false),
  (8926, $$BETO$$, 'CD', $$Leopards Group SARL (société privée congolaise, Kinshasa)$$, $$Leopards Group SARL ; directeur des publications Christian Okende ; le site antérieur Politico.cd avait pour fondateur et directeur de publication Litsani Choukran$$, ARRAY['commercial_generalist']::text[], NULL, $$Héritier de Politico.cd, site d’actualité politique congolais lancé en 2014 et rebaptisé BETO (« nous » en kikongo) ; projets de déclinaisons BETO TV et BETO FM.$$, $$Site d’information générale sur la RDC (politique, économie, sécurité, culture), qui revendique une « souveraineté médiatique » congolaise face aux médias internationaux. Aucune affiliation gouvernementale ou partisane documentée ; aucune étude indépendante de sa ligne éditoriale trouvée.$$, 'low', $$Éditeur et responsables identifiés par les mentions légales et les pages du site ; aucune source indépendante. Notre robot reçoit une réponse 403 sur la page d’accueil.$$, $$[{"url": "https://beto.cd/mentions-legales/", "note": "Mentions légales : éditeur Leopards Group SARL (RCCM CD/KNM/RCCM/21-B-00152), directeur des publications Christian Okende", "category": "self_described", "accessed_at": "2026-10-16"}, {"url": "https://beto.cd/politico-cd-est-devenu-beto-cd/", "note": "Politico.cd est devenu BETO ; mission : informer, éduquer, inspirer ; « souveraineté médiatique »", "category": "self_described", "accessed_at": "2026-10-16"}]$$::jsonb, true),
  (8913, $$Hespress Français$$, 'MA', $$MarocAds (privée)$$, $$Frères Hassan et Amin El Guennouni (fondateurs) ; édition francophone de Hespress$$, ARRAY['independent', 'commercial_generalist']::text[], NULL, $$Édition en français de Hespress, site lancé en février 2007 par les frères El Guennouni et devenu le média en ligne le plus consulté du Maroc.$$, $$Même éditeur et même profil que Hespress (édition arabe), dont le profil existant est marqué à réévaluer : des accusations de proximité avec le pouvoir ont été rapportées par certains médias sans preuve de propriété formelle.$$, 'medium', $$Repris du profil de Hespress : fondateurs et société éditrice identifiés par Media Ownership Monitor Maroc ; allégations non corroborées.$$, $$[{"url": "https://maroc.mom-gmr.org/en/media/detail/outlet/hespress/", "note": "Media Ownership Monitor Maroc : Hespress, MarocAds, frères El Guennouni", "category": "media_research", "accessed_at": "2026-10-16"}]$$::jsonb, true),
  (8953, $$Novo Jornal$$, 'AO', $$Tolerância, S.A. (groupe Nova Vaga), société privée ; propriété disputée en justice$$, $$Álvaro Sobrinho (ancien président de la banque BESA), déclaré seul propriétaire par le tribunal provincial de Luanda dans une décision provisoire frappée d’appel ; son frère Emanuel Madaleno en revendiquait le contrôle$$, ARRAY['independent', 'commercial_generalist']::text[], NULL, $$Hebdomadaire d’information générale lancé le 25 janvier 2008 ; propriété de Tolerância, S.A. (groupe Nova Vaga) depuis 2016. Depuis fin 2023, conflit entre les frères Sobrinho et Madaleno pour son contrôle, avec une intrusion dans les locaux dénoncée par le directeur Armindo Laureano (en poste depuis 2020), ensuite visé par une campagne de désinformation en ligne.$$, $$L’un des principaux titres angolais non contrôlés par l’État, connu pour une couverture critique de la politique, de l’économie et de la corruption ; instabilité actionnariale en cours.$$, 'medium', $$Propriété et litige documentés par la presse angolaise et un média lusophone spécialisé ; issue de l’appel non vérifiée.$$, $$[{"url": "https://diadefecho.com/p/semanario-angolano-novo-jornal-disputado", "note": "Litige entre Álvaro Sobrinho et Emanuel Madaleno ; Tolerância S.A. (Nova Vaga) ; directeur Armindo Laureano visé par une campagne en ligne", "category": "press", "accessed_at": "2026-10-16"}, {"url": "https://angola24horas.com/sociedade/item/28576-madaleno-perde-novo-jornal-em-tribunal-jornal-afirma-que-foi-decisao-judicial-cautelar-de-natureza-provisoria", "note": "Le journal précise que la décision du tribunal est une mesure conservatoire provisoire", "category": "press", "accessed_at": "2026-10-16"}, {"url": "https://novojornal.co.ao/", "note": "Hebdomadaire d’information générale édité à Luanda", "category": "self_described", "accessed_at": "2026-10-16"}]$$::jsonb, true),
  (8912, $$Sunday Express (Lesotho)$$, 'LS', $$Africa Media Holdings (groupe de presse privé, Maseru)$$, $$Africa Media Holdings ; PDG Basildon Peta, journaliste zimbabwéen exilé, éditeur du Lesotho Times$$, ARRAY['independent', 'commercial_generalist']::text[], NULL, $$Hebdomadaire du dimanche du groupe qui publie le Lesotho Times. Le groupe a subi de fortes pressions : Basildon Peta poursuivi pour diffamation pénale (infraction déclarée inconstitutionnelle en 2018 à la suite de son recours) ; le rédacteur en chef du Lesotho Times, Lloyd Mutungamiri, grièvement blessé par balles en 2016, des militaires ayant ensuite été jugés.$$, $$Hebdomadaire d’information générale. Aucune affiliation partisane documentée. Aucune étude indépendante de sa ligne éditoriale propre trouvée.$$, 'medium', $$Éditeur et attaques contre le groupe documentés par Wikipédia, le CPJ et le Southern Africa Litigation Centre.$$, $$[{"url": "https://en.wikipedia.org/wiki/Basildon_Peta", "note": "Basildon Peta, PDG d’Africa Media Holdings, éditeur du Lesotho Times et du Sunday Express", "category": "reference", "accessed_at": "2026-10-16"}, {"url": "https://cpj.org/2016/07/lesotho-editor-in-critical-condition-after-shootin/", "note": "CPJ : rédacteur en chef du Lesotho Times grièvement blessé par balles (juillet 2016)", "category": "press_freedom", "accessed_at": "2026-10-16"}, {"url": "https://www.amnesty.org/en/latest/news/2017/12/lesotho-trial-of-soldiers-for-shooting-newspaper-editor-offers-hope-of-justice-2/", "note": "Amnesty International : procès de militaires pour la tentative d’assassinat du rédacteur en chef (décembre 2017)", "category": "press_freedom", "accessed_at": "2026-10-16"}, {"url": "https://cpj.org/2018/05/lesotho-constitutional-court-declares-criminal-def/", "note": "CPJ : la Cour constitutionnelle invalide la diffamation pénale à la suite du recours de Basildon Peta (2018)", "category": "press_freedom", "accessed_at": "2026-10-16"}]$$::jsonb, false),
  (8964, $$Mohale FM$$, 'LS', $$Africa Media Holdings (groupe de presse privé, Maseru)$$, $$Africa Media Holdings ; PDG Basildon Peta$$, ARRAY['commercial_generalist']::text[], NULL, $$Radio commerciale de Maseru (106,9 MHz), membre du groupe qui publie le Lesotho Times et le Sunday Express ; date de lancement non documentée.$$, $$Radio musicale et d’information. Aucune affiliation partisane documentée ; aucune étude indépendante de sa ligne éditoriale trouvée.$$, 'medium', $$Appartenance au groupe établie par le pied de page du site ; groupe documenté par Wikipédia.$$, $$[{"url": "https://mohalefm.co.ls/", "note": "Pied de page : « A member of Africa Media Holdings » ; 106,9 MHz", "category": "self_described", "accessed_at": "2026-10-16"}, {"url": "https://en.wikipedia.org/wiki/Basildon_Peta", "note": "Basildon Peta, PDG d’Africa Media Holdings, éditeur du Lesotho Times et du Sunday Express", "category": "reference", "accessed_at": "2026-10-16"}]$$::jsonb, false),
  (8928, $$Jornal Desafio$$, 'MZ', $$Société anonyme à participation majoritaire de l’État (Sociedade do Notícias, S.A.)$$, $$Sociedade do Notícias, S.A. ; actionnaire majoritaire : l’État mozambicain via l’IGEPE (Instituto de Gestão das Participações do Estado)$$, ARRAY['public_state', 'specialist']::text[], NULL, $$Hebdomadaire sportif de la Sociedade do Notícias, éditeur du quotidien Notícias (fondé en 1926) et de l’hebdomadaire Domingo.$$, $$Journal consacré au sport. State Media Monitor classe l’éditeur « Captured Public » : en 2024, la mission d’observation électorale de l’UE a mesuré un net déséquilibre en faveur du FRELIMO et de son candidat dans le quotidien Notícias, titre phare du groupe. Aucune analyse propre à Desafio trouvée.$$, 'high', $$Éditeur et actionnariat public documentés par State Media Monitor (2026) ; contenu sportif. Le domaine du site ne se résolvait pas le 2026-10-16 (serveurs DNS refusant les requêtes).$$, $$[{"url": "https://statemediamonitor.com/2026/05/sociedade-de-noticias/", "note": "State Media Monitor : Sociedade do Notícias classée « Captured Public » ; État majoritaire via l’IGEPE ; publie Notícias, Domingo et Desafio ; biais documenté par la mission d’observation de l’UE (2024)", "category": "media_research", "accessed_at": "2026-10-16"}]$$::jsonb, false),
  (8933, $$Jornal Domingo$$, 'MZ', $$Société anonyme à participation majoritaire de l’État (Sociedade do Notícias, S.A.)$$, $$Sociedade do Notícias, S.A. ; actionnaire majoritaire : l’État mozambicain via l’IGEPE (Instituto de Gestão das Participações do Estado)$$, ARRAY['public_state']::text[], NULL, $$Hebdomadaire du dimanche publié depuis les années 1980 par la Sociedade do Notícias, éditeur du quotidien Notícias (fondé en 1926) et de l’hebdomadaire sportif Desafio.$$, $$Hebdomadaire d’information générale. State Media Monitor classe l’éditeur « Captured Public » : en 2024, la mission d’observation électorale de l’UE a mesuré un net déséquilibre en faveur du FRELIMO et de son candidat dans le quotidien Notícias, titre phare du groupe. Aucune analyse propre à Domingo trouvée.$$, 'high', $$Éditeur et actionnariat public documentés par State Media Monitor (2026). Le domaine du site ne se résolvait pas le 2026-10-16 (serveurs DNS refusant les requêtes).$$, $$[{"url": "https://statemediamonitor.com/2026/05/sociedade-de-noticias/", "note": "State Media Monitor : Sociedade do Notícias classée « Captured Public » ; État majoritaire via l’IGEPE ; publie Notícias, Domingo et Desafio ; biais documenté par la mission d’observation de l’UE (2024)", "category": "media_research", "accessed_at": "2026-10-16"}]$$::jsonb, false),
  (8929, $$Desert Radio$$, 'NA', $$Free Press of Namibia (société privée éditrice de The Namibian)$$, $$Free Press of Namibia, éditeur de The Namibian, rattaché à la Namibia Media Trust (structure fiduciaire sans actionnaires privés, selon le profil existant de The Namibian)$$, ARRAY['independent', 'commercial_generalist']::text[], NULL, $$Radio d’information lancée en octobre 2021 à Windhoek par le quotidien The Namibian (Free Press of Namibia), présentée par son rédacteur en chef Tangeni Amupadhi comme « une oasis d’information dans le désert ».$$, $$Actualité, débats, documentaires et interaction avec les auditeurs. Aucune affiliation gouvernementale ou partisane documentée ; ligne éditoriale propre non évaluée.$$, 'medium', $$Propriétaire et lancement documentés par The Namibian, maison mère de la station.$$, $$[{"url": "https://www.namibian.com.na/desert-radio-an-oasis-of-information/", "note": "The Namibian (8 octobre 2021) : lancement de Desert Radio par le groupe, à Windhoek", "category": "self_described", "accessed_at": "2026-10-16"}, {"url": "https://www.namibian.com.na/desert-radio-hits-dstv-gotv/", "note": "The Namibian : Desert Radio diffusée sur DStv et GoTV", "category": "self_described", "accessed_at": "2026-10-16"}]$$::jsonb, true),
  (8949, $$Seychelles Nation$$, 'SC', $$Quotidien public (propriété de l’État seychellois), publié par la National Information Services Agency (NISA)$$, $$Gouvernement des Seychelles, via la National Information Services Agency (agence publique créée en 2010)$$, ARRAY['public_state']::text[], NULL, $$Héritier du Seychelles Bulletin ; devenu « Nation » à l’indépendance le 29 juin 1976, puis « Seychelles Nation » en 1984.$$, $$Seul quotidien national (lundi au samedi, en anglais, français et créole), diffusé aux ministères, entreprises et abonnés. Wikipédia le décrit comme le porte-voix du gouvernement, couvrant toutes les questions gouvernementales.$$, 'high', $$Propriété publique et éditeur documentés par Wikipédia et la mention de copyright du site (NISA).$$, $$[{"url": "https://en.wikipedia.org/wiki/Seychelles_Nation", "note": "Propriété du gouvernement des Seychelles, publié par la NISA ; décrit comme porte-voix du gouvernement", "category": "reference", "accessed_at": "2026-10-16"}, {"url": "https://www.nation.sc/", "note": "Copyright : National Information Services Agency", "category": "self_described", "accessed_at": "2026-10-16"}]$$::jsonb, false),
  (1066, $$On.ge$$, 'GE', $$On.ge LLC (société privée géorgienne), détenue par BMG LLC$$, $$BMG LLC (Business Media Georgia, média économique fondé en 2016) ; bénéficiaires effectifs de BMG non identifiés dans les sources consultées$$, ARRAY['commercial_generalist']::text[], NULL, $$Média en ligne actif depuis 2015, qui réunit un portail d’actualité, un magazine, une agence de « bonnes nouvelles » et d’autres services ; racheté par BMG, qui l’a placé avec son agence d’information économique sous une direction commune.$$, $$Se présente comme un média numérique à but lucratif, dont la politique éditoriale repose sur une couverture impartiale et éthique (code éditorial publié). Dans le paysage médiatique géorgien très polarisé, aucune évaluation indépendante de sa ligne ni de celle de BMG n’a été trouvée.$$, 'medium', $$Propriété établie par la page « À propos » du site (On.ge LLC, détenue par BMG LLC) ; propriétaires de BMG et date du rachat non vérifiés.$$, $$[{"url": "https://on.ge/about", "note": "Page « À propos » : portail détenu par On.ge LLC, elle-même détenue par BMG LLC ; média à but lucratif ; code éditorial", "category": "self_described", "accessed_at": "2026-10-16"}]$$::jsonb, true);
DO $$
DECLARE bad int; n int;
BEGIN
  -- Each target must be the active publisher of that name in that country, and must not have a profile yet.
  SELECT count(*) INTO bad FROM prof x
   WHERE NOT EXISTS (SELECT 1 FROM publishers p JOIN countries c ON c.id = p.country_id
                      WHERE p.id = x.publisher_id AND p.name = x.name AND c.iso_code = x.iso AND p.feed_status = 'active')
      OR EXISTS (SELECT 1 FROM editorial_profiles e WHERE e.publisher_id = x.publisher_id);
  IF bad > 0 THEN RAISE EXCEPTION '% of 11 publishers are not the expected outlet or already have a profile - nothing changed', bad; END IF;
  INSERT INTO editorial_profiles (publisher_id, ownership_type, owner, classification_tags, political_party_association, historical_context,
    current_context, confidence, evidence_summary, evidence_sources, classification_date, last_reviewed, evidence_date, review_required)
  SELECT publisher_id, ownership_type, owner, classification_tags, political_party_association, historical_context,
    current_context, confidence, evidence_summary, evidence_sources, DATE '2026-10-16', DATE '2026-10-16', DATE '2026-10-16', review_required FROM prof;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 11 THEN RAISE EXCEPTION 'inserted %, expected 11', n; END IF;
END $$;
SELECT 'profile|' || p.id || '|' || p.name || '|' || array_to_string(e.classification_tags, ',') || '|' || e.confidence || '|review ' || e.review_required
       || '|' || jsonb_array_length(e.evidence_sources) || ' sources'
  FROM editorial_profiles e JOIN publishers p ON p.id = e.publisher_id WHERE e.publisher_id IN (8952, 8926, 8913, 8953, 8912, 8964, 8928, 8933, 8929, 8949, 1066) ORDER BY p.id;
SELECT 'gap|' || count(*) || ' active publishers still without a profile'
  FROM publishers p LEFT JOIN editorial_profiles e ON e.publisher_id = p.id WHERE p.feed_status = 'active' AND e.id IS NULL;
ROLLBACK;
SELECT 'rolledback|' || count(*) || ' profiles for these publishers' FROM editorial_profiles WHERE publisher_id IN (8952, 8926, 8913, 8953, 8912, 8964, 8928, 8933, 8929, 8949, 1066);
